#include "stock_profile_service.hpp"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <cstdio>
int checks=0;void ck(bool b,const char*why){if(!b)throw std::runtime_error(why);++checks;}
template<class F>void reject(F f,const char*why){bool failed=false;try{f();}catch(...){failed=true;}ck(failed,why);}
QByteArray bytes(QString path){QFile f(path);if(!f.open(QIODevice::ReadOnly))throw std::runtime_error("Owned fixture missing");return f.readAll();}
void write(QString path,QByteArray data){QFile f(path);if(!f.open(QIODevice::WriteOnly)||f.write(data)!=data.size())throw std::runtime_error("Owned fixture write failed");}
int main(int argc,char**argv){QCoreApplication app(argc,argv);try{
 auto f=QJsonDocument::fromJson(bytes(QString::fromLocal8Bit(argv[1]))).object();auto id=f["id"].toString(),at=f["at"].toString();QTemporaryDir root(QString::fromLocal8Bit(argv[2])+"/profile-cache-XXXXXX");if(!root.isValid())throw std::runtime_error("Private output directory unavailable");root.setAutoRemove(false);auto folder=root.filePath("cache");StockProfileCache cache(folder);auto empty=cache.capture(id,at);ck(!QDir(folder).exists(),"Read-only empty capture created directory");ck(empty.baseline.isEmpty()&&empty.packet["companyName"].isNull(),"Empty cache invented data");auto original=stockProfile::merge(id,f["responses"].toObject(),{},at);cache.save(id,original,empty.baseline,[]{return true;});auto file=cache.filePath(id);auto durable=bytes(file);auto saved=cache.capture(id,at);ck(saved.packet["sources"].toObject()["CompanySurvey"].toObject()["cached"].toBool(),"Disk capture omitted cache label");ck(durable==bytes(file),"Capture wrote cache file");ck(saved.packet["companyName"]==original["companyName"],"Actual stored profile changed company");ck(cache.filePath("SZ:stock:000001")!=cache.filePath("SH:index:000001"),"Same-code index/stock cache collision");auto unsupported=cache.capture("SH:index:000001",at);ck(unsupported.packet["sources"].toObject()["CompanySurvey"].toObject()["status"]=="unsupported"&&!QFileInfo::exists(cache.filePath("SH:index:000001")),"Unsupported index touched stock cache");reject([&]{cache.save(id,original,saved.baseline,[]{return false;});},"Owner cancellation committed cache");ck(bytes(file)==durable,"Cancelled cache save changed original");
 write(file,durable+"\n");auto changed=bytes(file);reject([&]{cache.save(id,original,saved.baseline,[]{return true;});},"Changed whole-file cache bypassed CAS");ck(bytes(file)==changed,"Stale CAS replaced newer file");write(file,durable);auto foreign=QJsonDocument::fromJson(durable).object();foreign["schema"]="foreign-cache/v1";write(file,QJsonDocument(foreign).toJson());auto foreignBytes=bytes(file);reject([&]{cache.capture(id,at);},"Foreign cache accepted");ck(bytes(file)==foreignBytes,"Foreign cache repaired/replaced");write(file,"not JSON");auto corrupt=bytes(file);reject([&]{cache.capture(id,at);},"Corrupt cache accepted");ck(bytes(file)==corrupt,"Corrupt cache recreated");write(file,durable);auto before=cache.capture(id,at);auto later=QString("2026-11-15T01:02:03.123456789+08:00");QJsonObject responses{{"BusinessAnalysis",QJsonObject{{"error","构造刷新失败"},{"at",later}}}};auto failed=stockProfile::merge(id,responses,before.packet,later);cache.save(id,failed,before.baseline,[]{return true;});auto fallback=cache.capture(id,later);ck(fallback.packet["sources"].toObject()["BusinessAnalysis"].toObject()["status"]=="cached-after-failure","Actual cache dropped failed-attempt state");ck(fallback.packet["sources"].toObject()["BusinessAnalysis"].toObject()["fetchedAt"]==at,"Actual cache advanced original successful clock");
 auto out=QJsonDocument(QJsonObject{{"checks",checks},{"cacheFilesReal",true},{"foreignCorruptPreserved",true},{"cas",true},{"ownerCancel",true},{"actualProviderFetch",false}}).toJson(QJsonDocument::Compact);std::printf("%s\n",out.constData());return 0;
 }catch(const std::exception&e){std::fprintf(stderr,"%s at check %d\n",e.what(),checks);return 1;}}
